schema_ddl:
CREATE TABLE clienti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE portafoglio (
    id SERIAL PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    nome TEXT NOT NULL,
    data_creazione DATE NOT NULL
);

CREATE TABLE posizioni (
    id SERIAL PRIMARY KEY,
    portafoglio_id INT NOT NULL REFERENCES portafoglio(id),
    rendimento NUMERIC(5,2) CHECK (rendimento BETWEEN 0 AND 100),
    importo NUMERIC(12,2) CHECK (importo >= 0),
    data_apertura DATE NOT NULL,
    data_chiusura DATE
);

CREATE INDEX idx_posizioni_portafoglio ON posizioni(portafoglio_id);
CREATE INDEX idx_portafoglio_cliente ON portafoglio(cliente_id);
